// Pass password_enc through — alice-mail-reader decrypts internally
const mailbox = $('Split: One Mailbox at a Time').first().json;
const lastUid = mailbox.last_uid || 0;
return [{ json: {
  mailboxId: mailbox.id,
  ownerId: mailbox.owner_id,
  host: mailbox.imap_host,
  port: mailbox.imap_port,
  username: mailbox.imap_username,
  passwordEnc: mailbox.password_enc,
  ssl: mailbox.ssl_enabled,
  lastUid,
  syncInterval: mailbox.sync_interval || 15,
  sinceDate: (lastUid === 0) && mailbox.start_date ? mailbox.start_date : null
} }];

// Process fetched emails: classify with Ollama, store in Weaviate
const axios = require('axios');
const fetchResult = $json;
const ctx = $('Prepare Mailbox Data').first().json;
const emails = fetchResult.emails || [];
const maxUid = fetchResult.max_uid || ctx.lastUid;

if (emails.length === 0) {
  return [{ json: { processed: 0, wichtig: [], maxUid, storedEmails: [] } }];
}

const WEAVIATE_URL = 'http://weaviate:8080';
const OLLAMA_URL = 'http://ollama-3090:11434';
const wichtigEmails = [];
// PROJ-53: mails actually inserted into Weaviate this run (deduped ones are excluded).
// Drives both the per-mail MQTT publish and the attachment import downstream.
const storedEmails = [];
let processedCount = 0;

for (const em of emails) {
  try {
    // Deduplicate: check if message_id + mailbox_id already in Weaviate
    const uniqueId = `${ctx.mailboxId}::${em.message_id || em.uid}`;
    const dedupeGql = {
      query: `{ Get { Email(where: { operator: And, operands: [ { path: ["messageId"], operator: Equal, valueText: ${JSON.stringify(uniqueId)} }, { path: ["mailboxId"], operator: Equal, valueText: ${JSON.stringify(ctx.mailboxId)} } ] } limit: 1) { _additional { id } } } }`
    };
    let alreadyExists = false;
    try {
      const dedupeRes = await axios.post(`${WEAVIATE_URL}/v1/graphql`, dedupeGql, { timeout: 5000 });
      const existing = dedupeRes.data?.data?.Get?.Email || [];
      alreadyExists = existing.length > 0;
    } catch(e) { /* Weaviate temporarily unavailable, skip dedupe */ }
    if (alreadyExists) continue;

    // Classify + summarize with Ollama (non-blocking on failure)
    let category = 'unklassifiziert';
    let summary = '';
    try {
      const prompt = `Du bist ein E-Mail-Klassifikator. Klassifiziere diese E-Mail und gib eine kurze Zusammenfassung (2-3 Sätze auf Deutsch).\n\nAbsender: ${em.sender}\nBetreff: ${em.subject}\nVorschau: ${em.body_preview || ''}\n\nAntworte NUR mit validem JSON: {"kategorie": "Wichtig|Werbung|Social Media|Spam", "zusammenfassung": "..."}\nKeine anderen Texte.`;
      const ollamaRes = await axios.post(`${OLLAMA_URL}/api/generate`, {
        model: 'qwen3.5:27b-q4_K_M',
        prompt,
        stream: false,
        options: { temperature: 0.1, num_predict: 200 }
      }, { timeout: 15000 });
      const raw = (ollamaRes.data?.response || '').trim();
      // Extract JSON from response (LLM might add thinking tokens)
      const jsonMatch = raw.match(/\{[^{}]+\}/);
      if (jsonMatch) {
        const parsed = JSON.parse(jsonMatch[0]);
        category = parsed.kategorie || 'unklassifiziert';
        summary = parsed.zusammenfassung || '';
      }
    } catch(e) { /* Ollama unavailable or parse error: store without classification */ }

    // Store in Weaviate
    const attachmentsText = (em.attachments || []).map(a => `${a.name} (${a.mime_type}, ${a.size_bytes} bytes)`);
    const weaviateObj = {
      class: 'Email',
      properties: {
        messageId: uniqueId,
        mailboxId: ctx.mailboxId,
        imapUid: String(em.uid),
        subject: em.subject || '',
        sender: em.sender || '',
        senderName: em.sender ? em.sender.replace(/<[^>]+>/, '').trim() : '',
        recipients: [em.recipients || ''],
        date: em.date ? new Date(em.date).toISOString() : new Date().toISOString(),
        category,
        summary,
        attachments: attachmentsText,
        hasAttachments: (em.attachments || []).length > 0,
        content: em.body_preview || ''
      }
    };
    const insertRes = await axios.post(`${WEAVIATE_URL}/v1/objects`, weaviateObj, { timeout: 10000 });
    processedCount++;

    // PROJ-53: remember the new object UUID for the MQTT thumbnail trigger
    // and keep the raw mail (incl. attachment metadata) for the import step.
    storedEmails.push({
      weaviate_uuid: insertRes.data?.id || null,
      uid: em.uid,
      message_id: em.message_id || '',
      subject: em.subject || '',
      sender: em.sender || '',
      date: em.date || '',
      body_preview: em.body_preview || '',
      attachments: em.attachments || []
    });

    if (category === 'Wichtig') {
      wichtigEmails.push({
        sender: em.sender,
        subject: em.subject,
        date: em.date,
        summary
      });
    }
  } catch(e) {
    // Skip individual email errors, continue processing
  }
}

return [{ json: { processed: processedCount, wichtig: wichtigEmails, maxUid, storedEmails } }];

// Send proactive notifications for 'Wichtig' emails
const { wichtig } = $json;
if (!wichtig || wichtig.length === 0) return $input.all();

// Passthrough — actual insert happens in PG: Send Notifications below
return $input.all();

