const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-mail-sync", node: "Code: Import Attachments" } });
const axios = require('axios');
const fs = require('fs');
const path = require('path');

// PROJ-53: per-attachment classification + NAS import for newly stored mails.
// Runs once per sync batch; iterates the mails that "Process + Classify + Store Emails"
// actually inserted into Weaviate (skipped/deduped mails are not in that list).
const ctx = $('Prepare Mailbox Data').first().json;
const prev = $input.first().json;
const storedEmails = prev.storedEmails || [];

// Base list mirrors alice-dms-path-worker. The video/audio entries below are a
// PROJ-53-only extension: they are NOT part of the shared DMS allowlist, because
// the DMS pipeline has no schema for them - here they are routed by extension
// into plain filesystem folders (Image/, Video/, Audio/) without any LLM call.
const SUPPORTED_EXTENSIONS = new Set([
  '.pdf','.txt','.md','.docx','.doc','.xlsx','.xls','.odt','.ods',
  '.jpg','.jpeg','.png','.webp','.heic','.tif','.tiff',
  // PROJ-53 iteration 2 additions (video)
  '.mp4','.mov','.avi','.mkv','.webm',
  // PROJ-53 iteration 2 additions (audio)
  '.mp3','.wav','.m4a','.ogg','.flac'
]);
const IMAGE_EXTENSIONS = new Set(['.jpg','.jpeg','.png','.webp','.heic','.tif','.tiff']);
const VIDEO_EXTENSIONS = new Set(['.mp4','.mov','.avi','.mkv','.webm']);
const AUDIO_EXTENSIONS = new Set(['.mp3','.wav','.m4a','.ogg','.flac']);
const PLAINTEXT_EXTENSIONS = new Set(['.txt','.md']);
const PDF_EXTENSIONS = new Set(['.pdf']);
const IMAGE_JUNK_MAX_BYTES = 20480;
// Upper bound checked from the /fetch metadata BEFORE calling /attachment: the
// attachment crosses the wire base64-encoded and is held in memory twice (base64
// string + Buffer) inside the shared n8n container, so an oversized attachment
// could OOM every other workflow, not just this import. The DMS pipeline itself
// is file-based and has no such ceiling (alice-dms-path-worker only demotes
// >100 MB to low priority), hence a dedicated, tighter limit for this path.
const ATTACHMENT_MAX_BYTES = 52428800; // 50 MB
// VALID_SCHEMAS stays exactly the five DMS schemas - it also validates the LLM's
// answer, so Video/Audio must NOT leak in here (the LLM must never return them).
const VALID_SCHEMAS = ['Invoice','BankStatement','Document','Contract','SecuritySettlement'];
// Folders this workflow may write into = the five schemas plus the three
// extension-routed media folders (Image added in PROJ-53 iteration 3). Used only
// to gate the resolved target folder.
const VALID_TARGET_FOLDERS = new Set([...VALID_SCHEMAS, 'Image', 'Video', 'Audio']);
const NAS_AI_ROOT = '/mnt/nas/ai';
const MAIL_READER_URL = 'http://alice-mail-reader:8007';
const OLLAMA_URL = 'http://ollama-3090:11434';
let ollamaModel = 'qwen3.5:27b-q4_K_M'; try { ollamaModel = $env.OLLAMA_MODEL_DMS || 'qwen3:14b'; } catch(e) {}

function prefilterAttachment(att) {
  const ext = path.extname(att.name || '').toLowerCase();
  if (!SUPPORTED_EXTENSIONS.has(ext)) return { keep: false, reason: 'unsupported_extension', ext };
  const size = Number(att.size_bytes || 0);
  if (size > ATTACHMENT_MAX_BYTES) return { keep: false, reason: 'too_large', ext, size };
  const isImage = IMAGE_EXTENSIONS.has(ext) || String(att.mime_type || '').startsWith('image/');
  if (isImage && size < IMAGE_JUNK_MAX_BYTES) return { keep: false, reason: 'image_junk', ext };
  return { keep: true, reason: null, ext };
}

// Extension-based routing (PROJ-53 iteration 2): image/video/audio never reach the
// LLM - their content cannot be classified into a DMS schema anyway. Returns the
// target folder name, or null when the attachment must go through classification.
function routeByExtension(ext, mimeType) {
  const mime = String(mimeType || '');
  if (IMAGE_EXTENSIONS.has(ext) || mime.startsWith('image/')) return 'Image';
  if (VIDEO_EXTENSIONS.has(ext) || mime.startsWith('video/')) return 'Video';
  if (AUDIO_EXTENSIONS.has(ext) || mime.startsWith('audio/')) return 'Audio';
  return null;
}

// PDF full text via alice-mail-reader (PROJ-53 iteration 2). n8n Code nodes cannot
// require pdf-parse, so extraction lives in the Python service. Any failure returns
// '' and the caller falls back to filename + mail context, as for Office formats.
async function fetchPdfText(ctxData, uid, attachmentIndex) {
  try {
    const r = await axios.post(`${MAIL_READER_URL}/attachment-text`, {
      host: ctxData.host, port: ctxData.port, ssl: ctxData.ssl,
      username: ctxData.username, password_enc: ctxData.passwordEnc,
      folder: 'INBOX', uid: String(uid), attachment_index: attachmentIndex
    }, { timeout: 120000 });
    return String(r.data?.text || '');
  } catch(e) {
    logger.warn(`[PROJ-53] PDF text extraction failed (uid=${uid} idx=${attachmentIndex}): ${e.message}`);
    return '';
  }
}

function shortenSender(sender) {
  const raw = String(sender || '');
  const angle = raw.match(/<([^>]+)>/);
  const addr = angle ? angle[1] : raw;
  const local = addr.includes('@') ? addr.split('@')[0] : addr;
  const cleaned = local.replace(/[^A-Za-z0-9._-]+/g, '-').replace(/^-+|-+$/g, '');
  return (cleaned || 'unknown').slice(0, 40);
}

function mailDateStamp(dateStr) {
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return 'unknown-date';
  return d.toISOString().slice(0, 10);
}

function sanitizeFilename(name) {
  return String(name || 'attachment').replace(/[/\\]/g, '_').replace(/[\x00-\x1f]/g, '').replace(/^\.+/, '').trim() || 'attachment';
}

function buildBaseFilename(mailDate, sender, originalName) {
  return `${mailDateStamp(mailDate)}_${shortenSender(sender)}_${sanitizeFilename(originalName)}`;
}

function resolveCollision(targetDir, baseName) {
  const ext = path.extname(baseName);
  const stem = ext ? baseName.slice(0, -ext.length) : baseName;
  if (!fs.existsSync(path.join(targetDir, baseName))) return baseName;
  for (let i = 1; i < 1000; i++) {
    const candidate = `${stem}_${i}${ext}`;
    if (!fs.existsSync(path.join(targetDir, candidate))) return candidate;
  }
  return `${stem}_${Date.now()}${ext}`;
}

function buildClassificationPrompt(mail, attName, textPreview) {
  return 'You are a document classifier for attachments of an email.\n' +
    'Classify the attachment into EXACTLY ONE of the following types:\n' +
    '- Invoice: invoice number, gross/net amount, VAT rate, due date, line items\n' +
    '- BankStatement: IBAN, opening/closing balance, list of bookings, statement period\n' +
    '- SecuritySettlement: ISIN, depot number, security name, buy/sell/dividend, quantity and price\n' +
    '- Contract: contract parties, sign date, start/end date, notice period, recurring cost\n' +
    '- Document: generic correspondence, forms, certificates or notices that match none of the above\n' +
    'If you cannot decide, use "unclear".\n\n' +
    'Email subject: ' + (mail.subject || '') + '\n' +
    'Email sender: ' + (mail.sender || '') + '\n' +
    'Email body preview: ' + String(mail.body_preview || '').slice(0, 1000) + '\n' +
    'Attachment filename: ' + attName + '\n' +
    'Attachment text preview: ' + (textPreview ? String(textPreview).slice(0, 4000) : '(no extractable text - classify from filename and email context)') + '\n\n' +
    'Respond ONLY with a JSON object: {"document_type": "<Type|unclear>", "confidence": <0-1>}';
}

function parseClassification(responseStr) {
  const parsed = JSON.parse(responseStr);
  const t = parsed.document_type;
  let confidence = parseFloat(parsed.confidence);
  if (isNaN(confidence)) confidence = 0;
  confidence = Math.max(0, Math.min(1, confidence));
  if (t === 'unclear') return { document_type: 'unclear', confidence };
  if (!VALID_SCHEMAS.includes(t)) return null;
  return { document_type: t, confidence };
}

async function callOllama(prompt, temperature) {
  const resp = await axios.post(`${OLLAMA_URL}/api/generate`, {
    model: ollamaModel, prompt, stream: false, format: 'json',
    options: { temperature, num_predict: 300 }
  }, { timeout: 120000 });
  return resp.data.response || '';
}

// Two-attempt classification, mirroring alice-dms-classify-document (PROJ-78).
// Returns null when the LLM is unreachable -> attachment is skipped (no blind import).
async function classifyAttachment(mail, attName, textPreview) {
  const prompt = buildClassificationPrompt(mail, attName, textPreview);
  let result = null;
  let ollamaReachable = false;
  try {
    const raw = await callOllama(prompt, 0);
    ollamaReachable = true;
    result = parseClassification(raw);
  } catch(e) {
    if (e instanceof SyntaxError) ollamaReachable = true;
  }
  if (!result) {
    try {
      const raw2 = await callOllama(prompt, 0.3);
      ollamaReachable = true;
      result = parseClassification(raw2);
    } catch(e) {
      if (e instanceof SyntaxError) ollamaReachable = true;
    }
  }
  if (!ollamaReachable) return null;
  // Uncertain / unparseable but LLM answered -> Document fallback (PROJ-78 behaviour)
  if (!result || result.document_type === 'unclear') return { document_type: 'Document', confidence: result ? result.confidence : 0, fallback: true };
  return { ...result, fallback: false };
}

let imported = 0, skippedJunk = 0, skippedUnsupported = 0, skippedTooLarge = 0, failed = 0, routedByExtension = 0;

for (const mail of storedEmails) {
  const attachments = mail.attachments || [];
  if (attachments.length === 0) continue;

  for (let idx = 0; idx < attachments.length; idx++) {
    const att = attachments[idx];
    try {
      const pre = prefilterAttachment(att);
      if (!pre.keep) {
        // Image junk is expected/normal - not an error, no error log.
        if (pre.reason === 'image_junk') {
          skippedJunk++;
        } else if (pre.reason === 'too_large') {
          // Logged: unlike junk/unsupported this is a genuinely relevant document
          // that we deliberately refuse, so it must be visible to the admin.
          skippedTooLarge++;
          logger.warn(`[PROJ-53] Attachment skipped, exceeds ${ATTACHMENT_MAX_BYTES} bytes (uid=${mail.uid} file=${att.name} size=${pre.size})`);
        } else {
          skippedUnsupported++;
        }
        continue;
      }

      // Fetch the raw bytes via the new alice-mail-reader endpoint (PROJ-53 Baustein 1).
      let attData = null;
      try {
        const r = await axios.post(`${MAIL_READER_URL}/attachment`, {
          host: ctx.host, port: ctx.port, ssl: ctx.ssl,
          username: ctx.username, password_enc: ctx.passwordEnc,
          folder: 'INBOX', uid: String(mail.uid), attachment_index: idx
        }, { timeout: 120000 });
        attData = r.data;
      } catch(e) {
        logger.warn(`[PROJ-53] Attachment fetch failed (uid=${mail.uid} idx=${idx}): ${e.message}`);
        failed++;
        continue;
      }
      if (!attData || !attData.content_base64) {
        logger.warn(`[PROJ-53] Attachment fetch returned no content (uid=${mail.uid} idx=${idx})`);
        failed++;
        continue;
      }
      const buffer = Buffer.from(attData.content_base64, 'base64');

      // Extension routing first (PROJ-53 iteration 2): image/video/audio bypass the
      // LLM entirely. Only PDF/DOCX/XLSX/ODT/ODS/TXT/MD get classified.
      let targetFolder = routeByExtension(pre.ext, att.mime_type);
      let classification = null;

      if (targetFolder) {
        routedByExtension++;
        logger.info(`[PROJ-53] Routed by extension: ${att.name} -> ${targetFolder}/ (no LLM call)`);
      } else {
        // Text preview: plaintext types decode directly, PDF via /attachment-text.
        // Office formats still have no synchronous extractor (see PROJ-91) and are
        // classified from filename + mail context only.
        let textPreview = '';
        if (PLAINTEXT_EXTENSIONS.has(pre.ext)) {
          try { textPreview = buffer.toString('utf8').slice(0, 4000); } catch(e) { textPreview = ''; }
        } else if (PDF_EXTENSIONS.has(pre.ext)) {
          textPreview = await fetchPdfText(ctx, mail.uid, idx);
        }

        classification = await classifyAttachment(mail, att.name, textPreview);
        if (!classification) {
          logger.warn(`[PROJ-53] Classification skipped, Ollama unreachable (uid=${mail.uid} file=${att.name})`);
          failed++;
          continue;
        }
        targetFolder = classification.document_type;
      }

      // Defence in depth: the folder segment must never be attacker/LLM controlled.
      if (!VALID_TARGET_FOLDERS.has(targetFolder)) {
        logger.warn(`[PROJ-53] Refusing invalid target folder "${targetFolder}" (uid=${mail.uid} file=${att.name})`);
        failed++;
        continue;
      }

      const targetDir = path.join(NAS_AI_ROOT, targetFolder);
      try {
        fs.mkdirSync(targetDir, { recursive: true });
      } catch(e) {
        logger.warn(`[PROJ-53] Target folder not creatable (${targetDir}): ${e.message}`);
        failed++;
        continue;
      }

      const baseName = buildBaseFilename(mail.date, mail.sender, att.name);
      const finalName = resolveCollision(targetDir, baseName);
      const finalPath = path.join(targetDir, finalName);
      try {
        fs.writeFileSync(finalPath, buffer);
      } catch(e) {
        logger.warn(`[PROJ-53] Write failed (${finalPath}): ${e.message}`);
        failed++;
        continue;
      }

      imported++;
      logger.info(`[PROJ-53] Imported attachment: ${finalPath} (target=${targetFolder}, ` +
        (classification
          ? `confidence=${classification.confidence}, fallback=${classification.fallback})`
          : 'routed=extension)'));
    } catch(e) {
      logger.warn(`[PROJ-53] Unhandled attachment error (uid=${mail.uid} idx=${idx}): ${e.message}`);
      failed++;
    }
  }
}

const attachmentStats = { imported, routed_by_extension: routedByExtension, skipped_image_junk: skippedJunk, skipped_unsupported: skippedUnsupported, skipped_too_large: skippedTooLarge, failed };
logger.info(`[PROJ-53] Attachment import for mailbox ${ctx.mailboxId}: ${JSON.stringify(attachmentStats)}`);

return [{ json: { ...prev, attachmentStats } }];

// PROJ-53: fan out the stored mails so the MQTT node fires once per inserted
// Email object (n8n runs a node once per input item). Mails without a Weaviate
// UUID are dropped - there would be nothing for the thumbnailer to attach to.
const prev = $input.first().json;
const stored = (prev.storedEmails || []).filter(m => m.weaviate_uuid);
if (stored.length === 0) {
  return [{ json: { _no_mqtt: true } }];
}
return stored.map(m => ({ json: { _no_mqtt: false, weaviate_uuid: m.weaviate_uuid, subject: m.subject } }));
